import{_ as a,o as n,c as e,a5 as i}from"./chunks/framework.C5BPAM3s.js";const g=JSON.parse('{"title":"Types","description":"","frontmatter":{},"headers":[],"relativePath":"docs/types.md","filePath":"docs/types.md"}'),l={name:"docs/types.md"};function t(p,s,o,r,h,c){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to “Types”">​</a></h1><p>Types are mendatory. The compiler needs to know the type of every declaration.</p><h2 id="variables-constants" tabindex="-1">Variables / Constants <a class="header-anchor" href="#variables-constants" aria-label="Permalink to “Variables / Constants”">​</a></h2><p>Variables and Constants can get their type by explicitly declaring it.</p><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var foo:String;</span></span></code></pre></div><p>Or by infering it from its initializing Value.</p><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var foo = &quot;BAR&quot;</span></span></code></pre></div><p>One of those has to be present in the declaration.</p><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var foo // this is illegal</span></span></code></pre></div><h2 id="not-nullable-by-default" tabindex="-1">Not nullable by default <a class="header-anchor" href="#not-nullable-by-default" aria-label="Permalink to “Not nullable by default”">​</a></h2><p>Variables are not implicitly nullable.</p><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var a:String = &quot;&quot;</span></span>
<span class="line"><span>b = null // compiler error</span></span></code></pre></div><p>The null type must explicitly added to the variable type.</p><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var a:String|Null = &quot;&quot;</span></span>
<span class="line"><span>b = null // correct</span></span></code></pre></div><p>The typehint can be simplified with a nullable shothand.</p><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var a:?String = &quot;&quot;</span></span>
<span class="line"><span>b = null // correct</span></span></code></pre></div><p>The nullable shorthand can not be used in type unions</p><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var a:?String|Int = &quot;&quot;</span></span>
<span class="line"><span>b = null // compiler error</span></span></code></pre></div><h2 id="type-unions" tabindex="-1">Type Unions <a class="header-anchor" href="#type-unions" aria-label="Permalink to “Type Unions”">​</a></h2><p>Declarations are not limited to one type. Types can be combined in TypeUnions.</p><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var foo:Int|String = &quot;BAR&quot;</span></span>
<span class="line"><span>foo = 42</span></span></code></pre></div><p>The type of the assignment target must match the type of the assignment source.</p><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const foo:Int|String = &quot;BAR&quot;</span></span>
<span class="line"><span>const foo_the_second = foo // correct</span></span>
<span class="line"><span>const foo_too:Int|String = foo // correct</span></span>
<span class="line"><span>const also_foo:Int|String|Bool = foo // correct</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const not_foo:String = foo // compiler error</span></span></code></pre></div><p>TypeUnions can not contain Errors or ErrorSets. (see ErrorUnions)</p><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>error LookupError {</span></span>
<span class="line"><span>    NotFound</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const foo:LookupError|String; // compiler error</span></span></code></pre></div><h2 id="type-assureance" tabindex="-1">Type assureance <a class="header-anchor" href="#type-assureance" aria-label="Permalink to “Type assureance”">​</a></h2><p>If you assure the Interpreter, that a symbol has a specific type, you can use it with that type. This is possible by using <code>if</code>, <code>switch</code> or <code>@assert</code>.</p><h3 id="if-expression" tabindex="-1">if expression <a class="header-anchor" href="#if-expression" aria-label="Permalink to “if expression”">​</a></h3><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const foo:Int|String = 42</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if(typeOf(foo) == Int)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // in here foo can be read as Int</span></span>
<span class="line"><span>    const bar:Int = foo // correct</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// back in this scope, foo can only be read as Int|String</span></span>
<span class="line"><span>const bar:Int = foo // compiler error</span></span></code></pre></div><h3 id="type-switch" tabindex="-1">type switch <a class="header-anchor" href="#type-switch" aria-label="Permalink to “type switch”">​</a></h3><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const foo:Int|String = 42</span></span>
<span class="line"><span></span></span>
<span class="line"><span>switch(typeOf(foo))</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    case Int =&gt; {</span></span>
<span class="line"><span>        // in here foo can be read as Int</span></span>
<span class="line"><span>        const bar:Int = foo</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    case String =&gt; {</span></span>
<span class="line"><span>        // in here foo can be read as String</span></span>
<span class="line"><span>        const bar:String = foo</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// back in this scope, foo can only be read as Int|String</span></span>
<span class="line"><span>const bar:Int = foo // compiler error</span></span></code></pre></div><h3 id="assert" tabindex="-1">assert <a class="header-anchor" href="#assert" aria-label="Permalink to “assert”">​</a></h3><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const foo:Int|String = 42</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    @assert(typeOf(foo) == Int)</span></span>
<span class="line"><span>    // in here foo can be read as Int</span></span>
<span class="line"><span>    const bar:Int = foo</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// back in this scope, foo can only be read as Int|String</span></span>
<span class="line"><span>const bar:Int = foo // compiler error</span></span></code></pre></div><h3 id="writing-to-assured-type-variables" tabindex="-1">writing to assured type Variables <a class="header-anchor" href="#writing-to-assured-type-variables" aria-label="Permalink to “writing to assured type Variables”">​</a></h3><p>Writing to variables with an assured type is still possible as before. But this extends the type again.</p><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var foo:Int|String|Null = 42</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@assert(typeOf(foo) == Int)</span></span>
<span class="line"><span>// now foo can be read as Int</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const bar:Int = foo</span></span>
<span class="line"><span></span></span>
<span class="line"><span>foo = &quot;Bar&quot; // correct</span></span>
<span class="line"><span>// now foo can be read as Int|String</span></span>
<span class="line"><span></span></span>
<span class="line"><span>foo = true // compiler error (declaration of foo did not include type Bool)</span></span></code></pre></div><h1 id="named-types" tabindex="-1">Named types <a class="header-anchor" href="#named-types" aria-label="Permalink to “Named types”">​</a></h1><p>Types can be named to avoid writing types like <code>Null|String|MyAwesomeClass</code> everywhere.</p><div class="language-alpha-script"><button title="Copy Code" class="copy"></button><span class="lang">alpha-script</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Number = Int|Float</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const foo:Number // correct (foo has type Int|Float)</span></span></code></pre></div><h1 id="available-types" tabindex="-1">Available Types <a class="header-anchor" href="#available-types" aria-label="Permalink to “Available Types”">​</a></h1><ul><li>Void</li><li>Null</li><li>Error</li><li>anyerror</li><li>any</li><li>Bool</li><li>Int</li><li>Float</li><li>String</li></ul><h1 id="typing-variables" tabindex="-1">Typing Variables <a class="header-anchor" href="#typing-variables" aria-label="Permalink to “Typing Variables”">​</a></h1><div class="language-dough"><button title="Copy Code" class="copy"></button><span class="lang">dough</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var doughnut:String;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>doughnut = 5; // this is an error</span></span></code></pre></div><h1 id="type-inference" tabindex="-1">Type inference <a class="header-anchor" href="#type-inference" aria-label="Permalink to “Type inference”">​</a></h1><p>Types are infered at first assignment, when no type is specified.</p><div class="language-dough"><button title="Copy Code" class="copy"></button><span class="lang">dough</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var inferedType = 42; // this is Number</span></span>
<span class="line"><span></span></span>
<span class="line"><span>inferedType = false; // this is an compile error</span></span></code></pre></div><p>The assignment doesn&#39;t have to be at assignment:</p><div class="language-dough"><button title="Copy Code" class="copy"></button><span class="lang">dough</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var inferedType; // this has no type yet</span></span>
<span class="line"><span></span></span>
<span class="line"><span>inferedType = 42; // now it is of type Number</span></span>
<span class="line"><span>inferedType = false; // this is an compile error</span></span></code></pre></div><h1 id="type-unions-1" tabindex="-1">Type Unions <a class="header-anchor" href="#type-unions-1" aria-label="Permalink to “Type Unions”">​</a></h1><p>Variables can have more than one type:</p><div class="language-dough"><button title="Copy Code" class="copy"></button><span class="lang">dough</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var multiType:String or Number = 42; // this is Number</span></span>
<span class="line"><span>multiType = &quot;Bake it!&quot;; // this is valid</span></span>
<span class="line"><span>multiType = false; // this is an compile error</span></span></code></pre></div><h1 id="nullables" tabindex="-1">Nullables <a class="header-anchor" href="#nullables" aria-label="Permalink to “Nullables”">​</a></h1><p>Sometimes variables should have a Value or Null (i.e. if not set) As we&#39;ve already seen, <code>Type Unions</code> can be used for this:</p><div class="language-dough"><button title="Copy Code" class="copy"></button><span class="lang">dough</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var result:String or Null = null;</span></span>
<span class="line"><span>result = &quot;Yes!&quot;;</span></span></code></pre></div><p>To make this common case easier to type and read, we have the <code>Nullable</code> syntax instead of writing a <code>Type Union</code>:</p><div class="language-dough"><button title="Copy Code" class="copy"></button><span class="lang">dough</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var result:?String = null;</span></span>
<span class="line"><span>result = &quot;Yes!&quot;;</span></span></code></pre></div><p>Both syntaxes do the same under the hood. However the Nullable syntax can only applied to single identifiers (not inline Type Unions):</p><div class="language-dough"><button title="Copy Code" class="copy"></button><span class="lang">dough</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var result:?String or Bool = null; // this is an compile error</span></span>
<span class="line"><span>// instead you need to write it as an Type Union:</span></span>
<span class="line"><span>var result:String or Bool or Null = null; // this is an compile error</span></span></code></pre></div><h1 id="named-types-1" tabindex="-1">Named Types <a class="header-anchor" href="#named-types-1" aria-label="Permalink to “Named Types”">​</a></h1><p>Types can also be defined with a name and referenced later:</p><div class="language-dough"><button title="Copy Code" class="copy"></button><span class="lang">dough</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type BoolString = Bool or String;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>var result:BoolString = false;</span></span>
<span class="line"><span>result = &quot;empty&quot;;</span></span></code></pre></div><p>Since <code>named types</code> have a single identifier, we can (and should) use the Nullable syntax, when the variable should be nullable:</p><div class="language-dough"><button title="Copy Code" class="copy"></button><span class="lang">dough</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type BoolString = Bool or String;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>var result:?BoolString = false;</span></span>
<span class="line"><span>result = null;</span></span></code></pre></div>`,63)])])}const b=a(l,[["render",t]]);export{g as __pageData,b as default};
